"""agent_evolve -- multi-objective optimization driven by a language model.

The public surface is deliberately small. Five obligations describe your
problem (see :mod:`agent_evolve.contract`), one function runs it, and one
command tells you whether the model is beating chance on it::

    from agent_evolve import optimize
    result = optimize(my_problem, budget=40)

    $ agent_evolve check mypkg.problem:problem     # is the model earning its cost?

Everything the research stack uses is still importable from the module that
defines it, and the names this package used to re-export at top level still
resolve -- lazily, through ``__getattr__``, so importing the library no longer
pulls in 233 modules to hand back one function. They are not part of the
supported surface and are not listed in ``__all__``.
"""

from agent_evolve.api import optimize
from agent_evolve.contract import (
    Problem,
    ObjectiveSpec,
    ValidationOutcome,
    artifact_key,
    as_problem,
)
from agent_evolve.core.results import Candidate, SearchResult
from agent_evolve.harness.registry import harness_registry
from agent_evolve.proposers.random_proposer import RandomProposer

#: The one place the version is written. `pyproject.toml` declares
#: `dynamic = ["version"]` and reads this literal, so the distribution metadata
#: and the importable attribute cannot disagree.
__version__ = "0.4.0"

#: The supported public surface.
__all__ = [
    "optimize",
    "Problem",
    "ObjectiveSpec",
    "ValidationOutcome",
    "SearchResult",
    "Candidate",
    "as_problem",
    "artifact_key",
    "RandomProposer",
    "harness_registry",
    "__version__",
]

